"""Normalize release records at the input boundary.

This module owns change identity (replay/deduplication), the persisted
``applied`` journal, and the dependency graph plus its deterministic order.
It performs no IO and imports nothing from the other project modules.
"""


class JournalError(ValueError):
    pass


def _is_str(value, allow_empty=False):
    return isinstance(value, str) and (allow_empty or bool(value))


def _identity(row):
    """Return the comparison key that decides duplicate equality.

    Equality deliberately covers id, component, units and the *set* of
    dependencies: ``depends_on`` ordering carries no meaning, so two records
    that differ only in dependency order are the same change.
    """
    return (row["id"], row["component"], row["units"], frozenset(row["depends_on"]))


def _read_dependencies(row, seen_ids):
    depends_on = row.get("depends_on", [])
    if not isinstance(depends_on, list):
        raise JournalError("invalid-change")
    for dep in depends_on:
        # A dependency must be a nonempty string; the target's existence is a
        # graph concern handled later by build_order.
        if not _is_str(dep):
            raise JournalError("invalid-change")
    # Repeated dependency IDs are the same edge, not a new one.
    return sorted(set(depends_on))


def read_changes(records):
    """Validate change records and collapse identical duplicates.

    Duplicate detection happens before any accounting or graph work so that a
    repeated record can never inflate the budget sum or add a parallel edge.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    by_id = {}
    order = []
    for row in records:
        if (not isinstance(row, dict) or not _is_str(row.get("id"))
                or not _is_str(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row, None),
        }
        known = by_id.get(change["id"])
        if known is None:
            by_id[change["id"]] = change
            order.append(change["id"])
        elif _identity(known) != _identity(change):
            # Same ID with different content is ambiguous replay: fail closed
            # rather than picking one of the two interpretations.
            raise JournalError("conflicting-change")
        # Identical duplicate: already present, keep the first copy only.
    return [by_id[change_id] for change_id in order]


def read_applied(applied):
    """Validate the caller-supplied persisted release journal."""
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    ids = []
    for change_id in applied:
        if not _is_str(change_id):
            raise JournalError("invalid-change")
        ids.append(change_id)
    return sorted(set(ids))


def build_order(changes, applied_ids):
    """Return the full deterministic topological order of change IDs.

    ``changes`` must already be normalized by ``read_changes``.
    """
    known = {change["id"] for change in changes}
    # Missing graph targets and unknown replay entries are the same class of
    # broken reference, so both report unknown-dependency.
    for change in changes:
        for dep in change["depends_on"]:
            if dep not in known:
                raise JournalError("unknown-dependency")
    for change_id in applied_ids:
        if change_id not in known:
            raise JournalError("unknown-dependency")

    # Graph direction: an edge is stored as "prereq -> [dependents]", so an
    # in-degree counts unmet prerequisites and a node becomes eligible when
    # every prerequisite has been emitted.
    dependents = {change["id"]: [] for change in changes}
    indegree = {change["id"]: 0 for change in changes}
    for change in changes:
        for dep in change["depends_on"]:
            dependents[dep].append(change["id"])
            indegree[change["id"]] += 1

    # Ties are broken by lexicographic ID among currently eligible nodes, which
    # makes the order independent of input order.
    ready = sorted(node for node, degree in indegree.items() if degree == 0)
    order = []
    while ready:
        node = ready.pop(0)
        order.append(node)
        for follower in dependents[node]:
            indegree[follower] -= 1
            if indegree[follower] == 0:
                ready.append(follower)
        ready.sort()

    if len(order) != len(changes):
        # Whatever is left still has unmet prerequisites somewhere in the
        # remaining graph: a cycle. Detect a cycle anywhere, not just reachable
        # from a root, by checking the whole node set.
        raise JournalError("dependency-cycle")
    return order

