"""Compose policy and journal data into a plan."""
from journal import JournalError, build_order, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Order matters and is fixed: policy first, so a disallowed operation
        # reports its own code before any change content is examined.
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        order = build_order(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    by_id = {change["id"]: change for change in changes}
    applied_set = set(applied)

    if request["action"] == "rollback":
        # Reverse of the *full* deterministic order, restricted to applied
        # entries. Undo runs newest-first; applied entries that are not in the
        # topological tail still keep their relative reverse position.
        actions = [change_id for change_id in reversed(order) if change_id in applied_set]
        # The budget was validated above but does not cap rollback: an
        # emergency undo must not be blocked by a quota.
        return {"status": "ok", "actions": actions,
                "units": sum(by_id[change_id]["units"] for change_id in actions)}

    # plan replays first: applied changes satisfy dependencies but are not
    # emitted, so they never consume new budget.
    actions = [change_id for change_id in order if change_id not in applied_set]
    units = sum(by_id[change_id]["units"] for change_id in actions)
    if units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

