"""Compose policy and journal data into a plan."""
from journal import (
    JournalError,
    build_order,
    read_applied,
    read_changes,
    read_retain,
    retained_closure,
)
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Order matters and is fixed: policy first, so a frozen production
        # operation reports production-frozen before the change array, the
        # applied journal or the graph is examined -- a malformed graph under
        # production therefore still yields production-frozen, never a graph
        # error code. The returned budget is already capped by policy for the
        # environment, so the quota check below cannot be raised by a request
        # asking for more than the staging limit.
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        order = build_order(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    by_id = {change["id"]: change for change in changes}
    applied_set = set(applied)

    if request["action"] == "rollback":
        try:
            # ``retain`` applies to rollback only; a plan ignores it entirely
            # rather than rejecting it, so plan results stay byte-identical to
            # G1 for every request that omits the field.
            retained = read_retain(request.get("retain"), applied)
        except JournalError as exc:
            return failure(str(exc))
        # Retained changes and their transitive prerequisites are both applied,
        # so excluding the closure leaves exactly the changes that may be
        # undone. Reverse of the *full* deterministic order, restricted to that
        # remainder: undo runs newest-first and the original relative positions
        # are preserved instead of being re-sorted.
        keep = retained_closure(retained, changes)
        actions = [change_id for change_id in reversed(order)
                   if change_id in applied_set and change_id not in keep]
        # The budget was validated above but does not cap rollback: an
        # emergency undo must not be blocked by a quota.
        return {"status": "ok", "actions": actions,
                "units": sum(by_id[change_id]["units"] for change_id in actions)}

    # plan replays first: applied changes satisfy dependencies but are not
    # emitted, so they never consume new budget. Budget excess is judged on the
    # emitted sum, which is what a caller actually spends.
    actions = [change_id for change_id in order if change_id not in applied_set]
    units = sum(by_id[change_id]["units"] for change_id in actions)
    if units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

