journal.py.text:
"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _read_dependencies(value):
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    for dep in value:
        if not isinstance(dep, str) or not dep:
            raise JournalError("invalid-change")
    return frozenset(value)


def read_changes(records):
    """Validate records and collapse identical duplicates.

    Record identity is (id, component, units, dependency set): the dependency set
    is compared as a set, so ordering or repeats inside `depends_on` do not
    conflict. Two records sharing an id but differing in any of those fields are
    ambiguous -- picking one arbitrarily could emit the wrong work or the wrong
    graph edges -- so they fail with `conflicting-change` before any accounting.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row.get("depends_on", [])),
        }
        previous = seen.get(change["id"])
        if previous is None:
            seen[change["id"]] = change
            changes.append(change)
        elif previous != change:
            raise JournalError("conflicting-change")
    return changes


def read_applied(values, known_ids):
    """Validate the caller-supplied persisted journal.

    Applied entries are replay state, not graph input: planner treats them as
    already-satisfied dependencies. An id that is not among the known changes
    can be neither ordered nor rolled back, so it fails with
    `unknown-dependency` rather than being silently dropped.
    """
    if values is None:
        return frozenset()
    if not isinstance(values, list):
        raise JournalError("invalid-change")
    applied = set()
    for value in values:
        if not isinstance(value, str) or not value:
            raise JournalError("invalid-change")
        if value not in known_ids:
            raise JournalError("unknown-dependency")
        applied.add(value)
    return frozenset(applied)

planner.py.text:
"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, check_plan_budget, check_request, read_retain


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(rows):
    return {"status": "ok", "actions": [row["id"] for row in rows],
            "units": sum(row["units"] for row in rows)}


def topological_order(changes):
    """Full deterministic order over every change, regardless of `applied`.

    Edges point dependency -> dependent, so a node becomes eligible only once
    every entry in its `depends_on` has been emitted. Among the currently
    eligible nodes the smallest id wins, which is what makes the order stable no
    matter how the records arrived. A node left unplaceable while its
    dependencies exist means a cycle, reported as `dependency-cycle`.
    """
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in by_id:
                raise JournalError("unknown-dependency")
    waiting = {row["id"]: len(row["depends_on"]) for row in changes}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            dependents[dep].append(row["id"])
    ready = [change_id for change_id, count in waiting.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(by_id[current])
        for dependent in dependents[current]:
            waiting[dependent] -= 1
            if waiting[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    """Assemble a plan or rollback result, or the matching error object."""
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy runs before any graph work so a frozen environment can never
        # reach journal/planner and leak partial actions.
        action, budget = check_request(request)
        changes = read_changes(request.get("changes"))
        order = topological_order(changes)
        by_id = {row["id"]: row for row in order}
        applied = read_applied(request.get("applied"), by_id)
        if action == "rollback":
            kept = read_retain(request.get("retain"), applied)
            return success(rollback_rows(order, applied, kept))
        rows = plan_rows(order, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    # Accounting happens on emitted (post-replay, post-dedup) rows only, so
    # applied entries satisfy dependencies without consuming the quota.
    units = sum(row["units"] for row in rows)
    try:
        check_plan_budget(budget, units)
    except PolicyError as exc:
        return failure(str(exc))
    return success(rows)


def plan_rows(order, applied):
    """New work only, in the same deterministic order."""
    return [row for row in order if row["id"] not in applied]


def rollback_rows(order, applied, kept):
    """Reverse-deterministic order over applied rows, minus the retain closure.

    `kept` holds the requested ids; it expands here to those ids plus every
    *applied* transitive dependency they still need, because rolling back a
    dependency while its dependent stays applied would leave a broken state.
    Everything else applied follows the original reverse order unchanged, so
    retention removes rows without reordering the survivors.
    """
    by_id = {row["id"]: row for row in order}
    closure = set()
    stack = [change_id for change_id in kept if change_id in applied]
    while stack:
        current = stack.pop()
        if current in closure:
            continue
        closure.add(current)
        for dep in by_id[current]["depends_on"]:
            if dep in applied and dep not in closure:
                stack.append(dep)
    return [row for row in reversed(order)
            if row["id"] in applied and row["id"] not in closure]

