    ambiguous -- picking one arbitrarily could emit the wrong work or the wrong
    graph edges -- so they fail with `conflicting-change` before any accounting.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row.get("depends_on", [])),
        }
        previous = seen.get(change["id"])
        if previous is None:
            seen[change["id"]] = change
            changes.append(change)
        elif previous != change:
            raise JournalError("conflicting-change")
    return changes


def read_applied(values, known_ids):
    """Validate the caller-supplied persisted journal.

    Applied entries are replay state, not graph input: planner treats them as
    already-satisfied dependencies. An id that is not among the known changes
    can be neither ordered nor rolled back, so it fails with
    `unknown-dependency` rather than being silently dropped.
    """
    if values is None:
        return frozenset()
    if not isinstance(values, list):
        raise JournalError("invalid-change")
    applied = set()
    for value in values:
        if not isinstance(value, str) or not value:
            raise JournalError("invalid-change")
        if value not in known_ids:
            raise JournalError("unknown-dependency")
        applied.add(value)
    return frozenset(applied)

