"""Compose policy and journal data into a plan or rollback result."""
import heapq

from journal import JournalError, read_changes
from policy import PolicyError, limit_for


class GraphError(ValueError):
    pass


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes):
    """Return every change id in deterministic topological order.

    A change lists its prerequisites in `depends_on`; readiness is computed on
    that orientation, so a change is eligible only once every id it names is done
    (`blockers`). `dependents` is just the reverse index used to release those
    successors. Reversing this logic would emit dependents before their
    prerequisites, so the direction is fixed here and nowhere else.
    """
    known = {row["id"] for row in changes}
    # Whole-graph checks run before any ordering (the caller has already rejected
    # unknown applied ids), and missing targets are reported before cycles: a
    # dangling edge also leaves its node ineligible forever, so without this split
    # it would surface as a bogus `dependency-cycle`.
    for row in changes:
        for target in row["depends_on"]:
            if target not in known:
                raise GraphError("unknown-dependency")
    blockers = {}
    dependents = {ident: [] for ident in known}
    for row in changes:
        # Only duplicate edges are collapsed. A self edge (a in a's depends_on) is
        # deliberately KEPT: it is a one-node cycle, and dropping it here would
        # turn `a -> a` into a successful plan instead of `dependency-cycle`.
        unique = sorted(set(row["depends_on"]))
        blockers[row["id"]] = set(unique)
        for target in unique:
            dependents[target].append(row["id"])
    # Lexicographic tie-breaking: heap order over the currently eligible ids is
    # what makes the result independent of input order.
    ready = [ident for ident, pending in blockers.items() if not pending]
    heapq.heapify(ready)
    order = []
    while ready:
        ident = heapq.heappop(ready)
        order.append(ident)
        for dependent in dependents[ident]:
            pending = blockers[dependent]
            pending.discard(ident)
            if not pending:
                heapq.heappush(ready, dependent)
    if len(order) != len(known):
        # Only true cycles are left: every missing target was already rejected.
        raise GraphError("dependency-cycle")
    return order


def _replay_id(ident, applied):
    """Ids already in the caller's journal count as satisfied, not as new work."""
    return ident in applied


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes, applied_raw = read_changes(
            request.get("changes"),
            applied_unset="applied" not in request,
            applied=request.get("applied"),
        )
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    action = request.get("action")
    known = {row["id"] for row in changes}
    # An applied id absent from this request cannot be replayed: its units are
    # unknown, so treating it as satisfied would under-count real work. Checked
    # before graph validation (not after) so an unknown journal entry is always
    # reported as `unknown-dependency` and never masked by a cycle in the graph.
    for ident in applied_raw:
        if ident not in known:
            return failure("unknown-dependency")
    try:
        order = _topological_order(changes)
    except GraphError as exc:
        return failure(str(exc))
    applied = set(applied_raw)
    by_id = {row["id"]: row for row in changes}
    if action == "plan":
        # Already applied entries satisfy dependencies and cost nothing new, so
        # they are filtered before the budget comparison.
        emitted = [ident for ident in order if not _replay_id(ident, applied)]
        units = sum(by_id[ident]["units"] for ident in emitted)
        if units > budget:
            return failure("budget-exceeded")
        return {"status": "ok", "actions": emitted, "units": units}
    # rollback: reverse of the FULL topological order, filtered afterwards so a
    # dependent is always withdrawn before the prerequisite it relies on. The
    # budget only constrained shape in policy; it must not cap this list.
    emitted = [ident for ident in reversed(order) if _replay_id(ident, applied)]
    units = sum(by_id[ident]["units"] for ident in emitted)
    return {"status": "ok", "actions": emitted, "units": units}

